<!-- --------- новый код chat: поступление; выбранные списания удаляются вместе с изменением одной транзакцией -->
<template>
<WorkOrderDialog v-if="!selection" :title="remove?'Удалить поступление':receipt?'Изменить поступление':'Поступление материала'" :busy="busy" @close="$emit('close')"><form @submit.prevent="prepare"><div v-if="error" class="alert alert-danger">{{ error }}</div><p><strong>{{ material.name }}</strong> · {{ unit }}</p><fieldset :disabled="busy" class="border-0 p-0"><label class="form-label">Дата поступления</label><input v-model="form.date" type="date" min="1900-01-01" max="2200-12-31" required :disabled="remove" class="form-control form-control-sm mb-3"><label class="form-label">Количество</label><QuantityInputComponent v-model="form.quantity" :precision="3" required :disabled="remove" class="form-control form-control-sm" /><p v-if="remove" class="text-danger mt-2">Поступление будет удалено. Если остатка недостаточно, потребуется выбрать использование для удаления.</p><button class="btn btn-sm mt-3" :class="remove?'btn-danger':'btn-primary'">{{ remove?'Удалить поступление':'Сохранить' }}</button></fieldset></form></WorkOrderDialog>
<WarehouseUsageSelectionModal v-else :usages="selection.usages" :shortage="selection.shortage" :unit="unit" @close="selection=null" @selected="commit" />
</template>
<script setup>
import {ref,reactive} from 'vue';import api from '../../../api';import WorkOrderDialog from './WorkOrderDialog.vue';import WarehouseUsageSelectionModal from './WarehouseUsageSelectionModal.vue';import QuantityInputComponent from '../../QuantityInputComponent.vue';import {quantityText,localDate,scaledQuantity,workError} from './workOrderHelpers';
const props=defineProps({agreementId:[String,Number],material:Object,receipt:Object,remove:Boolean,unit:String});const emit=defineEmits(['close','saved']);const busy=ref(false),error=ref(''),selection=ref(null);const form=reactive({date:props.receipt?.date||localDate(),quantity:props.receipt?quantityText(props.receipt.quantity_thousandths):''});
const prepare=async()=>{if(busy.value)return;const quantity=props.remove?0:scaledQuantity(form.quantity,3);if(quantity===null||(!props.remove&&quantity<=0)){error.value='Укажите положительное количество до трёх знаков после запятой';return;}busy.value=true;error.value='';try{const {data}=await api.get(`/agreements/${props.agreementId}/warehouse/${props.material.ID}/history`);const old=props.receipt?data.receipts.find(r=>r.ID===props.receipt.ID):null;if(props.receipt&&!old)throw new Error('Поступление уже удалено');const balance=data.receipts.reduce((s,r)=>s+r.quantity_thousandths,0)-data.usages.reduce((s,u)=>s+u.quantity_thousandths,0);const shortage=(old?.quantity_thousandths||0)-quantity-balance;if(shortage>0){selection.value={usages:data.usages,shortage};}else{busy.value=false;await commit([]);}}catch(e){error.value=e.response?workError(e):e.message;}finally{busy.value=false;}};
const commit=async ids=>{if(busy.value)return;selection.value=null;busy.value=true;error.value='';try{const url=`/agreements/${props.agreementId}/warehouse/${props.material.ID}/receipts`;const payload={...form,remove_usage_ids:ids};if(props.remove)await api.delete(`${url}/${props.receipt.ID}`,{data:payload});else if(props.receipt)await api.patch(`${url}/${props.receipt.ID}`,payload);else await api.post(`${url}/create`,payload);emit('saved');}catch(e){error.value=workError(e);}finally{busy.value=false;}};
</script>
<!-- --------- конец нового кода chat -->
